class Solution {
  public boolean hasSpecialSubstring(String s, int k) {
    int i = 0, n = s.length();
    while (i < n) {
      int j = i;
      while (j < n && s.charAt(j) == s.charAt(i)) j++;
      if (j - i == k) return true; // a maximal run of exactly k equal characters
      i = j;
    }
    return false;
  }
}
